           </div>

           <div class="form-field" data-field="email">
             <label for="email-address">Email address <span class="required" aria-hidden="true">*</span></label>
             <input id="email-address" name="email" type="email" autocomplete="email" required aria-describedby="email-error">
             <div class="error" id="email-error" aria-live="polite"></div>
           </div>

           <div class="form-field" data-field="phone">
             <label for="phone-number">Phone number</label>
             <input id="phone-number" name="phone" type="tel" autocomplete="tel" inputmode="tel" aria-describedby="phone-hint phone-error" placeholder="+1 555 123 4567">
             <div class="hint" id="phone-hint">Optional. Use +1 555 123 4567 or 555-123-4567.</div>
             <div class="error" id="phone-error" aria-live="polite"></div>
           </div>
         </div>

         <div class="actions">
           <button type="submit">Send message</button>
         </div>

         <p class="status" id="form-status" role="status" aria-live="polite" hidden></p>
       </form>
     </section>
   </main>

